tool_input.command:
python3 - <<'EOF'
import ast, pathlib

lines = {
 "src/attr/_funcs.py": [421, 489],
 "src/attr/_make.py": [474,475,498,499,552,855,887,1046,1198,1205,1216,2094,2558,2648,2656,2690],
}
for path, targets in lines.items():
    tree = ast.parse(pathlib.Path(path).read_text())
    # build list of (start,end,name,type) for all defs
    defs = []
    def walk(node, prefix):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                name = prefix + child.name
                defs.append((child.lineno, child.end_lineno, name, type(child).__name__, child))
                walk(child, name + ".")
            else:
                walk(child, prefix)
    walk(tree, "")
    for t in targets:
        cands = [d for d in defs if d[0] <= t <= d[1]]
        cands.sort(key=lambda d: d[1]-d[0])
        inner = cands[0] if cands else None
        print(path, t, inner[2] if inner else "<module>", inner[3] if inner else "")
EOF

